UPDATE abt_variabel SET nama = 'BARIS IKRAR TALAK SAMPUL (OTOMATIS; kosong bila bukan cerai talak)', data_type = 'data_sql', sql_query = 'SELECT IFNULL((SELECT CONCAT(''<b>IKRAR TALAK</b> PMH '',IFNULL(CONCAT(DAY(i.penetapan_majelis_hakim),'' '',ELT(MONTH(i.penetapan_majelis_hakim),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.penetapan_majelis_hakim)),''-''),'' - PHS ikrar '',IFNULL(CONCAT(DAY(i.tanggal_penetapan_sidang_ikrar),'' '',ELT(MONTH(i.tanggal_penetapan_sidang_ikrar),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.tanggal_penetapan_sidang_ikrar)),''-''),'' - Sidang ikrar '',IFNULL(CONCAT(DAY(i.tgl_ikrar_talak),'' '',ELT(MONTH(i.tgl_ikrar_talak),''Januari'',''Februari'',''Maret'',''April'',''Mei'',''Juni'',''Juli'',''Agustus'',''September'',''Oktober'',''November'',''Desember''),'' '',YEAR(i.tgl_ikrar_talak)),''-'')) FROM perkara_ikrar_talak i WHERE i.perkara_id=#perkara_id# LIMIT 1),'''') AS data', locked = 1 WHERE no_var = 5829 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '529579987fcdfb5e50ae3bb4f69f57a7';
