UPDATE abt_variabel SET nama = 'CIRI PERKARA AWAL SAMPUL (OTOMATIS: ciri yang berlaku dan sudah diketahui saat daftar; tanpa ghaib, mafqud, verstek, rekonvensi, mediasi, sita)', data_type = 'data_sql', sql_query = 'SELECT IFNULL(NULLIF(TRIM(CONCAT_WS(CONCAT('' '',CHAR(183),'' ''),NULLIF(''#5802#'',''''),NULLIF(''#5803#'',''''),NULLIF(''#5805#'',''''),NULLIF(''#5806#'',''''),NULLIF(''#5809#'',''''),NULLIF(''#5810#'',''''),NULLIF(''#5811#'',''''),NULLIF(''#5812#'',''''),NULLIF(''#5813#'',''''),NULLIF(''#5814#'',''''),NULLIF(''#5815#'',''''),NULLIF(''#5816#'',''''),NULLIF(''#5822#'',''''),NULLIF(''#5823#'',''''),NULLIF(''#5824#'',''''),NULLIF(''#5825#'',''''),NULLIF(''#5826#'',''''),NULLIF(''#5827#'',''''))),''''),''- tidak ada ciri khusus -'') AS data', locked = 1 WHERE no_var = 5861 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '20c8e82ef6b9e019bd8e01c9bd97a5e8';
UPDATE abt_variabel SET nama = 'TURUT TERGUGAT SAMPUL (tiga nama sebaris; lebihnya "dan N lainnya" ke lampiran; kosong bila tidak ada)', data_type = 'data_sql', sql_query = 'SELECT CONCAT(''TURUT TERGUGAT ('',COUNT(*),'') '',GROUP_CONCAT(CASE WHEN a.urutan<=3 THEN CONCAT(ELT(a.urutan,''I'',''II'',''III'',''IV'',''V'',''VI'',''VII'',''VIII'',''IX'',''X'',''XI'',''XII'',''XIII'',''XIV'',''XV'',''XVI'',''XVII'',''XVIII'',''XIX'',''XX''),''. '',a.nama) END ORDER BY a.urutan SEPARATOR '' - ''),IF(COUNT(*)>3,CONCAT('' - dan '',COUNT(*)-3,'' lainnya (lampiran)''),'''')) AS data FROM perkara_pihak4 a WHERE a.perkara_id=#perkara_id# HAVING COUNT(*)>0', locked = 1 WHERE no_var = 5897 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '17bee59125a6c35d4c22787d55d908cb';
UPDATE abt_variabel SET nama = 'PEKERJAAN DAN ALAMAT PIHAK I SAMPUL AWAL (langsung dari SIPP)', data_type = 'data_sql', sql_query = 'SELECT CONCAT(''Pekerjaan: '',IFNULL(NULLIF(h.pekerjaan,''''),''-''),'' - Alamat: '',IFNULL(a.alamat,'''')) AS data FROM perkara_pihak1 a LEFT JOIN pihak h ON h.id=a.pihak_id WHERE a.perkara_id=#perkara_id# ORDER BY a.urutan LIMIT 1', locked = 1 WHERE no_var = 5830 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '914e271514adc2d8dc7dbed7246c61f0';
UPDATE abt_variabel SET nama = 'PEKERJAAN DAN ALAMAT PIHAK II SAMPUL AWAL (langsung dari SIPP)', data_type = 'data_sql', sql_query = 'SELECT CONCAT(''Pekerjaan: '',IFNULL(NULLIF(h.pekerjaan,''''),''-''),'' - Alamat: '',IFNULL(a.alamat,'''')) AS data FROM perkara_pihak2 a LEFT JOIN pihak h ON h.id=a.pihak_id WHERE a.perkara_id=#perkara_id# ORDER BY a.urutan LIMIT 1', locked = 1 WHERE no_var = 5831 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '2c23b172c991d455b70a72ee8d2f908b';
UPDATE abt_variabel SET nama = 'INTERVENSI SAMPUL AWAL (OTOMATIS: pihak intervensi dari SIPP, tiga nama sebaris; kosong bila tidak ada)', data_type = 'data_sql', sql_query = 'SELECT CONCAT(''INTERVENSI ('',COUNT(*),'') '',GROUP_CONCAT(CASE WHEN a.urutan<=3 THEN CONCAT(ELT(a.urutan,''I'',''II'',''III'',''IV'',''V'',''VI'',''VII'',''VIII'',''IX'',''X'',''XI'',''XII'',''XIII'',''XIV'',''XV'',''XVI'',''XVII'',''XVIII'',''XIX'',''XX''),''. '',a.nama) END ORDER BY a.urutan SEPARATOR '' - ''),IF(COUNT(*)>3,CONCAT('' - dan '',COUNT(*)-3,'' lainnya (lampiran)''),'''')) AS data FROM perkara_pihak3 a WHERE a.perkara_id=#perkara_id# HAVING COUNT(*)>0', locked = 1 WHERE no_var = 5847 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = 'b970ea532dee03e548984a230724f153';
